)","THE CUT FALLS AFTER A COMPLETE THOUGHT, NEVER MID-SENTENCE (R-09)","MUST SIT AFTER AT LEAST ONE DATA BLOCK","pointer-events none, user-select none on the blurred content","Must never interrupt an argument mid-sentence (family rule)"],"requires_binding":false,"rule_id":"R-09","gating_related":true},{"key":"BLK-PAYWALL","name":"In-article paywall band","renderer_component":"BlockPaywall","family":"H","family_name":"Gates & CTAs","allowed_piece_types":"GATED","piece_types":["ALL"],"chart_question":null,"binding_rule":"STATES WHAT IS BEHIND IT SPECIFICALLY · NAMES THE METER STATE · SAME COMPONENT AS THE MODAL","binds_to":"the free-read meter state","required_payload_fields":["kicker ''CONTINUE WITH PREMIUM''","meter state string (e.g. ''3 / 3 FREE READS USED'')","specific statement of what is behind the wall (not generic)","primary CTA label (e.g. ''Start 14-day trial'')","reassurance line (e.g. ''cancel anytime'')"],"constraints":["STATES WHAT IS BEHIND IT SPECIFICALLY — no generic ''subscribe to read more''","NAMES THE METER STATE","SAME COMPONENT AS THE MODAL — one implementation, two placements","2px ink border on #f6f4ee; ink CTA button with paper text"],"requires_binding":true,"rule_id":null,"gating_related":true},{"key":"BLK-ALERTCTA","name":"Turn this into an alert","renderer_component":"BlockAlertCta","family":"H","family_name":"Gates & CTAs","allowed_piece_types":"TRACKED SERIES","piece_types":["ALL"],"chart_question":null,"binding_rule":"PRE-FILLS THE ALERT FROM THE PIECE''S OWN SUBJECT · THE BEST CTA IN THE PRODUCT","binds_to":"the piece''s own subject (entity + tracked series) → the alert definition","required_payload_fields":["kicker ''KEEP WATCHING THIS''","alert headline — what will trigger the ping","expected event + date","pre-filled alert subject (entity, series, condition)","CTA label (''Create alert →'')"],"constraints":["PRE-FILLS THE ALERT FROM THE PIECE''S OWN SUBJECT — the reader must not re-specify it","1px ink border on #f6f4ee; ink CTA button","Must never interrupt an argument mid-sentence (family rule)"],"requires_binding":true,"rule_id":null,"gating_related":false},{"key":"BLK-DOWNLOAD","name":"Take the data","renderer_component":"BlockDownload","family":"H","family_name":"Gates & CTAs","allowed_piece_types":"DEEP DIVE · NOTE","piece_types":["DEEP DIVE","NOTE"],"chart_question":null,"binding_rule":"SHIPPING THE OBJECT IDS IS THE DIFFERENTIATOR — IT MAKES THE RESEARCH AUDITABLE","binds_to":"the lake object IDs behind every series in the piece","required_payload_fields":["count of downloadable series (e.g. ''Download 9 series'')","file format (.xlsx)","the lake object ID for every series in the file","kicker ''EVERY SERIES IS DOWNLOADABLE'' + explanatory line"],"constraints":["The .xlsx must carry the lake object IDs so any figure traces back to its filing","2px ink top rule; outlined (not filled) button — it is not the primary CTA"],"requires_binding":true,"rule_id":null,"gating_related":false}]'::jsonb) as s(
    key text, name text, renderer_component text, family text, family_name text,
    allowed_piece_types text, piece_types jsonb, chart_question text, binding_rule text,
    binds_to text, required_payload_fields jsonb, constraints jsonb, requires_binding boolean,
    rule_id text, gating_related boolean)
on conflict (key) do update set
  display_name = excluded.display_name, renderer_component = excluded.renderer_component,
  family = excluded.family, family_name = excluded.family_name,
  allowed_piece_types = excluded.allowed_piece_types, piece_types = excluded.piece_types,
  chart_question = excluded.chart_question, binding_rule = excluded.binding_rule,
  binds_to = excluded.binds_to, required_payload_fields = excluded.required_payload_fields,
  constraints = excluded.constraints, requires_binding = excluded.requires_binding,
  rule_id = excluded.rule_id, gating_related = excluded.gating_related, status = 'active';

-- grandfather the 8 seed-only keys (see the file header for why they survive)
update ops.story_blocks set status = 'legacy' where key in ('BLK-QUOTE', 'BLK-TABLE', 'BLK-CHART', 'BLK-SCORE', 'BLK-YIELD', 'BLK-COVERAGE', 'BLK-HOLDERS', 'BLK-FILING');

do $$ declare v_a int; v_l int; begin
  select count(*) into v_a from ops.story_blocks where status='active';
  select count(*) into v_l from ops.story_blocks where status='legacy';
  if v_a <> 61 then raise exception 'expected 61 active blocks, got %', v_a; end if;
  if v_l <> 8 then raise exception 'expected 8 legacy blocks, got %', v_l; end if;
  raise notice 'story_blocks: % active + % legacy', v_a, v_l;
end $$;
